ee:message.ee:set-payload:
%dw 2.0
ns mdm http://www.etb.com.co/Gateway/MDM_Data_Services
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
var request = payload.pqrActivityNotes
output text/xml
---
{
  soapenv#Envelope: {
    soapenv#Header: null,
    soapenv#Body: {
      mdm#Set_PQR_Actividad_Notas: {
        mdm#WSRequestHeader: {
          mdm#system: {
            mdm#name: request.requestHeader.system.name,
            mdm#correlationId: request.requestHeader.system.correlationId,
            mdm#processingServer: request.requestHeader.system.processingServer
          },
          mdm#property: {
            mdm#Property: request.requestHeader.property map ((item, index) -> 
            {
                mdm#name: item.name,
                mdm#value: item.value
            })
          }
        },
		mdm#WSRequestBody: {
		          mdm#id: request.requestBody.id,
		          mdm#PQR_number: request.requestBody.pqrNumber,
		          mdm#Activity_Number: request.requestBody.activityNumber,
		          mdm#Activity_Notes:
		          {
		              mdm#PQR_Actividad_Notas_Set_Body: request.requestBody.activityNotes map ((item, index) -> 
		              	mdm#Nota: item.note
		              )
		          },
		          mdm#set_type: request.requestBody.setType
		}
      }
    }
  }
}
